<script setup lang="ts">
import {ref,onMounted,nextTick} from 'vue';
const props=defineProps<{api:(path:string,method?:string,body?:unknown)=>Promise<any>,currentId:number}>();
const emit=defineEmits<{selfChanged:[]}>();
const items=ref<any[]>([]),permissions=ref<Record<string,string>>({}),presets=ref<Record<string,string[]>>({}),draft=ref<any>(null),dialog=ref<HTMLDialogElement>(),busy=ref(false),error=ref(''),notice=ref('');
const deleteTarget=ref<any>(null),deleteDialog=ref<HTMLDialogElement>();
async function askDelete(user:any){error.value='';deleteTarget.value=user;await nextTick();deleteDialog.value?.showModal();}
async function remove(){await run(async()=>{const id=deleteTarget.value.id;await props.api('/users/'+id+'?version='+deleteTarget.value.version,'DELETE');deleteDialog.value?.close();deleteTarget.value=null;if(id===props.currentId){emit('selfChanged');return;}notice.value='Пользователь удалён. Доступ закрыт, история действий сохранена.';await load();});}
const roles:Record<string,string>={admin:'Администратор',librarian:'Библиотекарь',viewer:'Наблюдатель'};
async function load(){const result=await props.api('/users');items.value=result.items;permissions.value=result.permissions;presets.value=result.presets;}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
async function open(user?:any){error.value='';draft.value=user?{...user,permissions:[...user.permissions],password:''}:{username:'',display_name:'',role:'viewer',permissions:['catalog.view'],active:true,password:''};await nextTick();dialog.value?.showModal();}
function chooseRole(){draft.value.permissions=[...(presets.value[draft.value.role]||[])];}
async function save(){await run(async()=>{const {id,...body}=draft.value;if(!body.password)delete body.password;await props.api('/users'+(id?'/'+id:''),id?'PUT':'POST',body);dialog.value?.close();draft.value=null;if(id===props.currentId){emit('selfChanged');return;}notice.value=id?'Права обновлены. Пользователю нужно войти заново.':'Пользователь создан.';await load();});}
onMounted(()=>run(load));
</script>
<template><section><div class="page-heading"><div><h1>Пользователи и права</h1><p>Администраторы имеют полный доступ. Для остальных сотрудников настройте разрешённые действия.</p></div><button class="primary" :disabled="busy" @click="open()">Создать пользователя</button><button :disabled="busy" @click="run(load)">Обновить список</button></div>
<p v-if="error&&!draft&&!deleteTarget" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
<div class="card table-wrap"><table><thead><tr><th>Имя / логин</th><th>Роль</th><th>Доступ</th><th></th></tr></thead><tbody><tr v-for="u in items" :key="u.id"><td>{{u.display_name}}<small class="block">{{u.username}}{{u.id===currentId?' · Вы':''}}</small></td><td>{{roles[u.role]}}</td><td>{{u.active?'Активен':'Заблокирован'}}</td><td><button :disabled="busy" @click="open(u)">Настроить права</button> <button class="danger-link" :disabled="busy" @click="askDelete(u)" :aria-label="'Удалить пользователя '+u.username">Удалить</button></td></tr></tbody></table></div></section>
<dialog ref="dialog" class="modal card users-dialog" aria-labelledby="user-dialog-title" @cancel="busy?$event.preventDefault():draft=null" @close="draft=null"><form v-if="draft" @submit.prevent="save"><h2 id="user-dialog-title">{{draft.id?'Настройки пользователя':'Новый пользователь'}}</h2><fieldset :disabled="busy" class="plain-fieldset"><div class="acquisition-grid"><label>ФИО пользователя<input v-model="draft.display_name" required maxlength="160"></label><label>Логин<input v-model="draft.username" required pattern="[A-Za-z0-9_.\-]{3,80}" autocomplete="off" placeholder="Латинские буквы, цифры, . _ -"></label><label>{{draft.id?'Новый пароль (оставьте пустым, чтобы сохранить)':'Пароль'}}<input v-model="draft.password" type="password" :required="!draft.id" minlength="8" maxlength="256" autocomplete="new-password"></label><label>Роль<select v-model="draft.role" @change="chooseRole"><option v-for="(label,value) in roles" :value="value">{{label}}</option></select></label></div>
<label class="check-label"><input type="checkbox" v-model="draft.active">Доступ разрешён</label><p>Снимите флажок, чтобы заблокировать вход и завершить сеансы пользователя.</p>
<p v-if="draft.role==='admin'">Полный доступ ко всем функциям, включая управление пользователями.</p><div v-else class="permission-grid"><label v-for="(label,value) in permissions" class="check-label"><input type="checkbox" :value="value" v-model="draft.permissions" :disabled="value==='catalog.view'">{{label}}</label></div>
<p>Роль задаёт начальный набор прав; флажками можно его изменить. Просмотр поступлений и списаний включается автоматически при выдаче права изменять их.</p>
<p v-if="draft.id===currentId">После изменения собственной учётной записи потребуется войти снова.</p></fieldset><p v-if="error" role="alert">{{error}}</p><div class="modal-actions"><button type="button" :disabled="busy" @click="dialog?.close()">Отмена</button><button class="primary" :disabled="busy">Сохранить пользователя</button></div></form></dialog>
<dialog ref="deleteDialog" class="modal card" aria-labelledby="delete-user-title" @cancel="busy?$event.preventDefault():deleteTarget=null" @close="deleteTarget=null"><template v-if="deleteTarget"><h2 id="delete-user-title">Удалить пользователя?</h2><p><strong>{{deleteTarget.display_name}}</strong> · {{deleteTarget.username}}</p><p>Пользователь исчезнет из списка, доступ будет закрыт, все его сеансы завершатся. История действий сохранится. Восстановление через интерфейс недоступно; логин останется зарезервирован.</p><p v-if="deleteTarget.id===currentId">Вы удаляете свою учётную запись. После удаления вы выйдете из системы.</p><p v-if="error" role="alert">{{error}}</p><div class="modal-actions"><button autofocus :disabled="busy" @click="deleteDialog?.close()">Отмена</button><button class="danger-button" :disabled="busy" @click="remove">Подтвердить удаление</button></div></template></dialog>
</template>
<style scoped>.users-dialog{width:min(780px,94vw);max-height:90vh;overflow:auto}.permission-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:14px;margin:22px 0}.check-label{margin-top:14px}</style>
